custom_css:
/* ============================================
   F.A.Y.E. O.S. 
   ============================================ */

@import url("https://fonts.googleapis.com/css2?family=Pixelify+Sans:wght@400;500;600;700&family=VT323&display=swap");

:root {
  --bunny-pink:        #9896bb; /* Deep Lavender (Main Panels) */
  --bunny-pink-dark:   #5d6da5; /* Periwinkle (Accents) */
  --bunny-rose:        #344979; /* Dark Indigo (Borders & Headers) */
  --bunny-blush:       #0e1120; /* Ultra-Pale Blue/Purple (App Background) */
  --bunny-cream:       #1a1f35; /* Crisp White (Message Boxes) */
  --bunny-muted:       #9896bb; /* Deep Lavender */
  --bunny-text:        #c8caee; /* Dark Indigo */
  --bunny-text-light:  #b0aed8; /* Periwinkle Light (Dark Mode) */
  --bunny-border:      #5d6da5; /* Periwinkle */
  --bunny-win-title:   #ffffff; /* Crisp White */
  --bunny-win-bg:      #1e2440; /* Soft Lavender (Popups) */
  --pixel-border:      2px solid var(--bunny-border);
  scrollbar-color: var(--bunny-pink-dark) var(--bunny-blush);
}

/* =====================
   GLOBAL TYPOGRAPHY
   ===================== */
body, .mes_text, p, input, textarea, select,
button:not([class*="fa-"]):not([class*="fa "]),
span:not([class*="fa-"]):not([class*="fa "]),
div:not([class*="fa-"]):not([class*="fa "]) {
  font-family: 'Pixelify Sans', monospace !important;
  color: var(--bunny-text);
}

.mes_text {
  font-family: 'Pixelify Sans', monospace !important;
  font-size: 14px;
  line-height: 1.7;
  color: var(--bunny-text) !important;
  text-shadow: none !important;
}

h1, h2, h3, h4, h5, h6,
.standoutHeader,
.ch_name .name_text,
.timestamp,
.mesIDDisplay,
.tokenCounterDisplay,
.mes_timer {
  font-family: 'VT323', monospace !important;
  color: var(--bunny-rose) !important;
  text-shadow: 1px 1px 0 var(--bunny-cream) !important;
  letter-spacing: 1.5px;
}

/* =====================
   GLOBAL BACKGROUND
   ===================== */
body {
  background-color: var(--bunny-blush) !important;
}

#chat::before {
  content: '';
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background-image: radial-gradient(circle, rgba(93, 109, 165, 0.25) 1px, transparent 1px);
  background-size: 8px 8px;
  pointer-events: none;
  z-index: 0;
}

/* =====================
   TOP BAR
   ===================== */
#top-bar {
  background: linear-gradient(to right, #5d6da5 0%, #9896bb 50%, #5d6da5 100%) !important;
  border-bottom: 3px solid var(--bunny-rose) !important;
  box-shadow: 0 3px 0 rgba(52, 73, 121, 0.3) !important;
}

.drawer-icon::before{
  color: var(--bunny-cream) !important;
  text-shadow: 1px 1px 0 rgba(52, 73, 121, 0.4) !important;
}

#ai-config-button .drawer-icon::before          { content: "AI" !important; font-family: 'VT323', monospace !important; font-weight: normal !important; font-size: 13px !important;  }
#sys-settings-button .drawer-icon::before       { content: "SYS" !important; font-family: 'VT323', monospace !important; font-weight: normal !important; font-size: 13px !important; }
#advanced-formatting-button .drawer-icon::before{ content: "FMT" !important; font-family: 'VT323', monospace !important; font-weight: normal !important; font-size: 13px !important; }
#WI-SP-button .drawer-icon::before              { content: "WLD" !important; font-family: 'VT323', monospace !important; font-weight: normal !important; font-size: 13px !important; }
#user-settings-button .drawer-icon::before      { content: "USR" !important; font-family: 'VT323', monospace !important; font-weight: normal !important; font-size: 13px !important; }
#backgrounds-button .drawer-icon::before        { content: "BG" !important;  font-family: 'VT323', monospace !important; font-weight: normal !important; font-size: 13px !important; }
#extensions-settings-button .drawer-icon::before{ content: "EXT" !important; font-family: 'VT323', monospace !important; font-weight: normal !important; font-size: 13px !important; }
#persona-management-button .drawer-icon::before { content: "ME" !important;  font-family: 'VT323', monospace !important; font-weight: normal !important; font-size: 13px !important; }
#rightNavHolder .drawer-icon::before {
  content: "CHR" !important;
  font-family: 'VT323', monospace !important; font-weight: normal !important; font-size: 13px !important; position: relative !important;
  top: 1.4px !important; }

/* =====================
   CHAT MESSAGES
   ===================== */
#chat {
  padding: 8px 12px !important;
  border: none !important;
  margin: 0 !important;
  background-color: rgba(14, 17, 32, 0.3) !important;
}

.mes {
  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin-bottom: 24px !important;
  position: relative !important;
}

.mes::after { display: none !important; content: none !important; }

/* Character Window */
.mes .mesAvatarWrapper {
  display: flex !important;
  flex-direction: row !important;
  position: relative !important;
  width: 100% !important;
  max-width: 460px !important;
  min-height: 152px !important;
  height: auto !important;
  padding: 26px 6px 6px 6px !important;
  margin: 0 0 -2px 4px !important;
  align-self: flex-start !important;
  background: var(--bunny-cream) !important;
  border: 2px solid var(--bunny-rose) !important;
  border-radius: 0 !important;
  box-shadow: 3px 3px 0 rgba(20,30,80,0.8) !important;
  gap: 6px !important;
  box-sizing: border-box !important;
  z-index: 10 !important;
}

/* User Window */
.mes[is_user="true"] .mesAvatarWrapper {
  flex-direction: row-reverse !important;
  align-self: flex-end !important;
  margin: 0 4px -2px 0 !important;
  box-shadow: -3px 3px 0 rgba(20,30,80,0.8) !important;
}

/* Window Title */
.mes .mesAvatarWrapper::before {
  content: " ☾ profile.exe" !important;
  position: absolute !important;
  top: 0 !important; left: 0 !important; right: 0 !important;
  height: 22px !important;
  background: linear-gradient(to right, #5d6da5 0%, #9896bb 50%, #5d6da5 100%) !important;
  color: var(--bunny-cream) !important;
  font-family: 'VT323', monospace !important; font-size: 13px !important; padding: 1px 8px !important;
  text-shadow: 1px 1px 0 rgba(52, 73, 121, 0.4) !important;
  border-bottom: 2px solid var(--bunny-rose) !important; letter-spacing: 0.5px !important;
  white-space: nowrap !important; overflow: hidden !important; display: block !important;
  box-sizing: border-box !important; line-height: 1.5 !important; z-index: 2 !important;
}

.mes[is_user="true"] .mesAvatarWrapper::before {
  content: "☾ user.exe" !important;
  background: linear-gradient(to right, #344979 0%, #5d6da5 50%, #344979 100%) !important;
}

/* Avatar */
.mes .mesAvatarWrapper .avatar {
  position: static !important;
  flex: 0 0 auto !important;
  width: 134px !important; height: 134px !important;
  min-width: 134px !important; max-width: 134px !important;
  border: 2px solid var(--bunny-rose) !important; border-radius: 0 !important;
  overflow: hidden !important; background-color: var(--bunny-blush) !important;
  box-shadow: 2px 2px 0 rgba(20,30,80,0.8) !important; margin: 0 !important; padding: 0 !important;
  display: block !important;
}
.mes .mesAvatarWrapper .avatar img, .mes .mesAvatarWrapper > img {
  width: 100% !important; height: 100% !important; object-fit: cover !important;
  object-position: top center !important; border-radius: 0 !important; display: block !important;
}

/* Dialog Pop-Up */
.mes .mesAvatarWrapper::after {
  content: "> loading char.bmp\A> status: online \25CF\A> mood: sleepy (_　_)。\A> hp: \2665 \2665 \2665 \2665 \2665\A> ready to chat \2665" !important;
  position: static !important; flex: 1 1 auto !important; min-width: 0 !important; height: 134px !important;
  white-space: pre !important; padding: 8px 10px !important;
  font-family: 'VT323', monospace !important; font-size: 14px !important; line-height: 18px !important;
  color: var(--bunny-text) !important; background: var(--bunny-cream) !important;
  border: 2px solid var(--bunny-rose) !important; border-radius: 0 !important;
  box-shadow: 2px 2px 0 rgba(20,30,80,0.8), inset 1px 1px 0 rgba(255, 255, 255, 0.05) !important;
  overflow: hidden !important; letter-spacing: 0.3px !important; box-sizing: border-box !important; display: block !important; width: auto !important;
}

.mes[is_user="true"] .mesAvatarWrapper::after {
  content: "> loading user.bmp\A> status: active \25CF\A> mood: lazy (´￢｀)\A> hp: \2661 \2661 \2661 \2661 \2661\A> ready to chat \2661" !important;
  background: #111626 !important;
}

/* Message Body */
.mes .mes_block {
  flex: 1 1 auto !important; min-width: 0 !important; width: 100% !important;
  margin-left: 0 !important; position: relative !important; display: flex !important; flex-direction: column !important;
}
.mes .mes_block::before {
  content: '' !important; display: block !important; height: 5px !important;
  background: linear-gradient(to right, #5d6da5, #9896bb, #5d6da5) !important;
  border: 2px solid var(--bunny-rose) !important; border-bottom: none !important;
}
.mes[is_user="true"] .mes_block::before {
  background: linear-gradient(to right, #344979, #5d6da5, #344979) !important;
}

.mes .ch_name {
  background-color: var(--bunny-pink) !important; border: 2px solid var(--bunny-rose) !important;
  border-top: none !important; border-bottom: 2px solid var(--bunny-muted) !important;
  padding: 2px 8px !important; border-radius: 0 !important;
  font-family: 'VT323', monospace !important; font-size: 15px !important;
  display: flex !important; align-items: center !important; gap: 6px !important; color: var(--bunny-cream) !important;
  text-shadow: 1px 1px 0 rgba(52, 73, 121, 0.3) !important;
}
.mes .ch_name::after {
  content: "_ [] X" !important;
  margin-left: auto !important;
  font-size: 10px !important;
  letter-spacing: 1px !important;
  color: var(--bunny-cream) !important;
  font-family: 'VT323', monospace !important;
  opacity: 0.8 !important;
  white-space: nowrap !important;
  flex-shrink: 0 !important;
}
.mes .name_text {
  font-family: 'VT323', monospace !important; font-size: 15px !important; color: var(--bunny-cream) !important; text-shadow: none !important;
}

.mes .mes_text {
  background-color: var(--bunny-cream) !important; border: 2px solid var(--bunny-rose) !important; border-top: none !important;
  padding: 10px 14px 12px !important;
  background-image: repeating-linear-gradient(to bottom, transparent, transparent 22px, rgba(152, 150, 187, 0.15) 22px, rgba(152, 150, 187, 0.15) 23px) !important;
  background-position: 0 30px !important; min-height: 40px !important; color: var(--bunny-text) !important;
}

.mes[is_user="true"] .ch_name { background-color: var(--bunny-pink-dark) !important; }
.mes[is_user="true"] .mes_text {
  background-color: #111626 !important;
  background-image: repeating-linear-gradient(to bottom, transparent, transparent 22px, rgba(93, 109, 165, 0.12) 22px, rgba(93, 109, 165, 0.12) 23px) !important;
}

/* =====================
   MARKDOWN INSIDE MESSAGES
   ===================== */
.mes_text em { color: var(--bunny-text-light) !important; font-style: italic; text-shadow: none !important; }
.mes_text strong { color: var(--bunny-text) !important; text-shadow: 1px 1px 0 rgba(198, 198, 232, 0.5) !important; }
.mes_text code {
  font-family: 'VT323', monospace !important; background-color: #111626 !important; border: 1px solid var(--bunny-border) !important;
  color: var(--bunny-text) !important; padding: 1px 6px; border-radius: 0 !important; font-size: 15px; box-shadow: 1px 1px 0 var(--bunny-border);
}
.mes_text blockquote {
  border-left: 4px solid var(--bunny-pink-dark) !important; background: #111626 !important;
  padding: 6px 12px !important; margin: 6px 0 !important; font-style: italic; color: var(--bunny-text-light) !important;
}

/* =====================
   SECTION HEADERS (ST UI panels)
   ===================== */
h4, .standoutHeader {
  background: var(--bunny-pink) !important;
  color: var(--bunny-cream) !important;
  font-family: 'VT323', monospace !important;
  border: 2px solid var(--bunny-border) !important;
  border-radius: 0 !important;
  padding: 4px 8px !important;
  text-shadow: none !important;
  letter-spacing: 1.5px;
}

/* =====================
   MESSAGE HEADINGS (inside chat)
   ===================== */
.mes_text h1, .mes_text h2, .mes_text h3,
.mes_text h4, .mes_text h5, .mes_text h6 {
  font-family: 'VT323', monospace !important;
  text-shadow: none !important;
  letter-spacing: 1.5px;
}

.mes_text h1 {
  display: block !important;
  border: 2px solid #344979 !important;
  box-shadow: 3px 3px 0 #5d6da5 !important;
  padding: 26px 10px 6px 10px !important;
  background: #111626 !important;
  font-size: 22px !important;
  text-transform: uppercase !important;
  color: #c8caee !important;
  position: relative !important;
}
.mes_text h1::before {
  content: '☾' !important;
  display: block !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  height: 22px !important;
  line-height: 20px !important;
  padding: 1px 8px !important;
  font-size: 14px !important;
  background: linear-gradient(to right, #5d6da5, #9896bb, #5d6da5) !important;
  color: #ffffff !important;
  border-bottom: 2px solid #344979 !important;
  text-shadow: 1px 1px 0 rgba(20,30,60,0.5) !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  font-family: 'VT323', monospace !important;
  box-sizing: border-box !important;
}
.mes_text h1::after {
  content: '_ [ ] X' !important;
  display: block !important;
  position: absolute !important;
  top: 0 !important;
  right: 8px !important;
  height: 22px !important;
  line-height: 20px !important;
  padding: 1px 0 !important;
  font-size: 11px !important;
  color: #ffffff !important;
  font-family: 'VT323', monospace !important;
  letter-spacing: 1px !important;
  pointer-events: none !important;
}

.mes_text h2 {
  display: block !important;
  font-size: 20px !important;
  text-transform: uppercase !important;
  color: #c8caee !important;
  border-bottom: 2px dashed #b0aed8 !important;
  padding: 0 0 3px 0 !important;
  background: transparent !important;
}
.mes_text h2::before { content: '>> ' !important; letter-spacing: 0 !important; }

.mes_text h3 {
  display: block !important;
  font-size: 18px !important;
  color: #b0aed8 !important;
  border-left: 3px dotted #9896bb !important;
  padding: 0 0 0 10px !important;
  background: transparent !important;
}
.mes_text h3::before { content: '>_ ' !important; }

.mes_text h4 {
  display: inline-block !important;
  font-size: 15px !important;
  color: #c8caee !important;
  background: #111626 !important;
  border: 1px solid #5d6da5 !important;
  padding: 1px 6px !important;
  text-shadow: none !important;
  letter-spacing: 1px !important;
}

.mes_text h5, .mes_text h6 {
  font-size: 14px !important;
  color: var(--bunny-text-light) !important;
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
}

/* =====================
   TIMESTAMP / META / SWIPE
   ===================== */
.mes .timestamp, .mes .tokenCounterDisplay, .mes .mesIDDisplay, .mes_timer {
  font-family: 'VT323', monospace !important; color: var(--bunny-rose) !important; opacity: 0.85; font-size: 12px !important;
}
.fa-chevron-right::before { display: inline !important; opacity: 1 !important; content: "⏭" !important; }
.fa-chevron-left::before { display: inline !important; opacity: 1 !important; content: "⏮" !important; }
.swipes-counter { font-family: 'VT323', monospace !important; color: var(--bunny-text-light) !important; font-size: 13px !important; }

/* =====================
   SCROLLBARS
   ===================== */
::-webkit-scrollbar { width: 12px; height: 12px; background: var(--bunny-blush); }
::-webkit-scrollbar-thumb { background: var(--bunny-pink-dark); border: 2px solid var(--bunny-rose); border-radius: 0 !important; }
::-webkit-scrollbar-thumb:hover { background: var(--bunny-rose); }
::-webkit-scrollbar-track { background: var(--bunny-blush); border: 1px solid var(--bunny-muted); }

/* =====================
   WINDOWS-STYLE DRAWER HEADERS & PANELS
   ===================== */
.inline-drawer-toggle.inline-drawer-header, .standoutHeader.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header, #extensions_settings2 .inline-drawer-toggle.inline-drawer-header {
  font-family: 'VT323', monospace !important; font-size: 15px; letter-spacing: 1px; text-transform: uppercase;
  background: linear-gradient(to right, #5d6da5 0%, #9896bb 50%, #5d6da5 100%) !important;
  color: var(--bunny-cream) !important; border: 2px solid var(--bunny-rose) !important; border-radius: 0 !important; padding: 4px 8px !important;
  box-shadow: inset -1px -1px 0 rgba(0, 0, 0, 0.4), inset 1px 1px 0 rgba(255, 255, 255, 0.15) !important;
  text-shadow: 1px 1px 0 rgba(52, 73, 121, 0.4) !important; gap: 8px;
}
.inline-drawer-toggle.inline-drawer-header::after {
  content: "_ [] X";
  float: right;
  font-size: 9px;
  opacity: 0.85;
  letter-spacing: 1px;
  color: var(--bunny-cream);
  font-family: 'VT323', monospace !important;
  white-space: nowrap;
  flex-shrink: 0;
  margin-left: 6px;
  align-self: center;
}
.fillLeft.openDrawer, .fillRight.openDrawer, .drawer-content { background-color: #16193a !important; border-radius: 0 !important; }

/* =====================
   POPUPS
   ===================== */
.popup, .floating_panel, #character_popup, #options, #floatingPrompt, #cfgConfig, #WorldInfo, #SnippetsExtensionWindow {
  background-color: var(--bunny-win-bg) !important; border: 2px solid var(--bunny-rose) !important; border-radius: 0 !important; box-shadow: 3px 3px 0 var(--bunny-border), 5px 5px 0 rgba(0, 0, 0, 0.5) !important;
}
.popup_header, .popup .title_bar, .ui-dialog-titlebar {
  background: linear-gradient(to right, #5d6da5 0%, #9896bb 50%, #5d6da5 100%) !important;
  color: var(--bunny-cream) !important; font-family: 'VT323', monospace !important; font-size: 16px !important;
  border-bottom: 2px solid var(--bunny-rose) !important; border-radius: 0 !important; padding: 4px 8px !important; text-shadow: 1px 1px 0 rgba(52, 73, 121, 0.4) !important;
}
.popup_close, .ui-dialog-titlebar-close {
  background-color: #1e2a47 !important; border: 1px solid #0a0f20 !important; color: var(--bunny-cream) !important; border-radius: 0 !important; font-family: 'VT323', monospace !important; box-shadow: 1px 1px 0 rgba(152, 150, 187, 0.5) !important;
}

/* =====================
   INPUTS & BUTTONS
   ===================== */
select, .form-control, .ui-widget-content, input[type="text"], input[type="search"], input[type="number"], textarea, .text_pole, .textarea_compact {
  background-color: var(--bunny-cream) !important; color: var(--bunny-text) !important; border: 2px solid var(--bunny-border) !important; border-radius: 0 !important; font-family: 'Pixelify Sans', monospace !important;
}
input:focus-visible, textarea:focus-visible, select:focus-visible { outline: 2px solid var(--bunny-rose) !important; border-color: var(--bunny-rose) !important; }

.menu_button, button, .btn {
  font-family: 'Pixelify Sans', monospace !important; background-color: var(--bunny-pink) !important; color: #ffffff !important; border: 2px solid var(--bunny-border) !important; border-radius: 0 !important;
  box-shadow: 1px 1px 0 rgba(255,255,255,0.1), 2px 2px 0 var(--bunny-rose) !important; text-shadow: 1px 1px 0 rgba(0,0,0,0.4) !important; filter: none !important; opacity: 1 !important;
}
.menu_button:hover, button:hover, .btn:hover { background-color: var(--bunny-pink-dark) !important; box-shadow: -1px -1px 0 rgba(255,255,255,0.1), -2px -2px 0 var(--bunny-rose) !important; }
.menu_button:active, button:active { box-shadow: inset 1px 1px 0 var(--bunny-rose) !important; transform: translate(1px, 1px); }

/* Select2 dropdown fix */
.select2-container .select2-selection--single,
.select2-container .select2-selection--multiple,
.select2-container--default .select2-selection--single,
.select2-container--default .select2-selection--multiple {
  background-color: var(--bunny-cream) !important;
  color: var(--bunny-text) !important;
  border: 2px solid var(--bunny-border) !important;
  border-radius: 0 !important;
  font-family: 'Pixelify Sans', monospace !important;
  height: auto !important;
}

.select2-container--default .select2-selection--single .select2-selection__rendered {
  color: var(--bunny-text) !important;
  font-family: 'Pixelify Sans', monospace !important;
  line-height: 28px !important;
}

.select2-dropdown {
  background-color: var(--bunny-cream) !important;
  border: 2px solid var(--bunny-rose) !important;
  border-radius: 0 !important;
}

.select2-results__option {
  color: var(--bunny-text) !important;
  font-family: 'Pixelify Sans', monospace !important;
}

.select2-results__option--highlighted {
  background-color: var(--bunny-pink-dark) !important;
  color: #ffffff !important;
}

/* =====================
   SEND FORM
   ===================== */
#form_sheld {
  padding-left: 0.5% !important; padding-right: 0.5% !important; border-top: 3px solid var(--bunny-rose) !important; padding-top: 4px !important; background-color: var(--bunny-blush) !important;
}
#nonQRFormItems {
  border: 2px solid var(--bunny-border) !important; border-radius: 0 !important; background-color: var(--bunny-cream) !important; box-shadow: inset 1px 1px 0 rgba(255,255,255,0.05), 2px 2px 0 var(--bunny-border) !important; position: relative !important;
}
#send_textarea { background: transparent !important; color: var(--bunny-text) !important; font-family: 'Pixelify Sans', monospace !important; font-size: 14px; border: none !important; box-shadow: none !important; padding: 10px 16px !important; }
#send_textarea::placeholder { font-size: 0px !important; }

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  content: "> waiting for user input..." !important; position: absolute !important; left: 50% !important; top: 50% !important; transform: translate(-50%, -50%) !important; color: var(--bunny-pink-dark) !important; font-family: 'VT323', monospace !important; font-size: 16px !important; opacity: 0.8 !important; pointer-events: none !important; z-index: 10 !important; white-space: nowrap !important; 
}

/* =====================
   CHECKBOXES & SLIDERS
   ===================== */
input[type='checkbox'] {
