  border: 2px solid var(--bunny-border) !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  transition: background 0.2s !important;
}

.ri-toggle-slider::before {
  content: '' !important;
  position: absolute !important;
  width: 11px !important;
  height: 11px !important;
  background: #ffffff !important;
  border: 1px solid var(--bunny-border) !important;
  border-radius: 0 !important;
  left: 1px !important;
  top: 1px !important;
  transition: transform 0.15s !important;
  transform: translateX(0) !important;
}

.ri-toggle-label input[type='checkbox']:checked + .ri-toggle-slider {
  background: var(--bunny-rose) !important;
  border-color: var(--bunny-rose) !important;
}

.ri-toggle-label input[type='checkbox']:checked + .ri-toggle-slider::before {
  transform: translateX(15px) !important;
}
